type UserPreferencesResult =
  | {
      data: unknown
      error?: never
    }
  | {
      data?: never
      error: string
    }

async function getUserPreferences(): Promise<UserPreferencesResult> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })

    if (!res.ok) {
      return { error: `Unable to load preferences (${res.status})` }
    }

    return { data: await res.json() }
  } catch {
    return { error: 'Unable to load preferences' }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      {'error' in preferences ? (
        <p>{preferences.error}</p>
      ) : (
        <pre>{JSON.stringify(preferences.data, null, 2)}</pre>
      )}
    </div>
  )
}

